/* zyb-scanassure.js - Scan Coverage Assurance page (scan-assurance.html). Reads /api/itam/scan-assurance: every connected asset with
 * its status, the reason it was not scanned and the fix; files the prepared rescan (POST /scan-assurance/rescan - a different
 * person approves each scan in Vulnerability Scans). No inline handlers; every value is escaped; requests are marked zybQuiet. */
(function () {
  'use strict';
  var esc = function (v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var $ = function (id) { return document.getElementById(id); };
  var RANK = { viewer: 0, analyst: 1, operator: 2, admin: 3 }, ROLE = 'viewer', V = null, FLT = 'failed', REASON = '';
  function req(m, u, b) { return new Promise(function (ok, bad) { var x = new XMLHttpRequest(); x.open(m, '/api/itam' + u); x.withCredentials = true; x.timeout = 120000; x.zybQuiet = true; if (b) x.setRequestHeader('Content-Type', 'application/json');
    x.onload = function () { var j = null; try { j = JSON.parse(x.responseText); } catch (e) { j = null; /* not JSON: shown as the HTTP status */ } if (x.status >= 200 && x.status < 300 && j) return ok(j); bad(Object.assign(new Error((j && j.error) || ('HTTP ' + x.status)), { status: x.status })); };
    x.onerror = x.ontimeout = function () { bad(Object.assign(new Error('IT Asset Management is not reachable'), { status: 0 })); }; x.send(b ? JSON.stringify(b) : null); }); }
  function toast(t) { var d = document.createElement('div'); d.setAttribute('role', 'status'); d.style.cssText = 'position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#1d2430;border:1px solid #2e3747;border-radius:10px;padding:10px 16px;z-index:9999;max-width:90vw'; d.textContent = t; document.body.appendChild(d); setTimeout(function () { d.remove(); }, 6000); }
  function tile(l, v, s, c) { return '<div class="t ' + (c || '') + '"><div class="l">' + esc(l) + '</div><div class="v">' + esc(v) + '</div><div class="s">' + esc(s || '') + '</div></div>'; }
  var STC = { scanned: 'ok', pending: 'info', excluded: '', failed: 'bad' };
  function load() { return req('GET', '/scan-assurance').then(function (v) { V = v; $('main').hidden = false; $('err').innerHTML = ''; draw(); }, function (e) { $('main').hidden = true;
    $('err').innerHTML = '<div class="card"><p>' + esc(e.status === 403 ? 'Asset names and addresses are internal: operators and administrators.' : e.status === 404 ? 'Scan Coverage Assurance is not installed yet - run the platform update.' : e.message) + '</p></div>'; }); }
  function draw() { var v = V, k = v.kpis;
    $('kk').innerHTML = tile('Coverage', k.coverage == null ? '—' : k.coverage + '%', 'scanned within ' + v.stale_days + ' days, of assessable assets', k.coverage == null ? '' : k.coverage >= 95 ? 'ok' : k.coverage >= 80 ? 'warn' : 'bad')
      + tile('Connected assets', k.connected, 'active, in the register') + tile('Not scanned', k.failed, k.persistent + ' for 2+ days', k.failed ? 'bad' : 'ok') + tile('In a scan now', k.pending, 'requested, approved or running', '')
      + tile('Left out on purpose', k.excluded, 'fragile or excluded - covered another way', '') + tile('Trend', v.trend.length > 1 ? v.trend[v.trend.length - 1].coverage + '%' : '—', v.trend.length > 1 ? 'from ' + v.trend[0].coverage + '% on ' + v.trend[0].day : 'one snapshot a day builds it', '');
    $('reasons').innerHTML = v.by_reason.length ? '<table><thead><tr><th>Reason</th><th>Assets</th><th>Fix</th></tr></thead><tbody>' + v.by_reason.map(function (r) { return '<tr data-reason="' + esc(r.reason) + '" style="cursor:pointer' + (REASON === r.reason ? ';outline:2px solid var(--info)' : '') + '"><td><b>' + esc(r.why) + '</b></td><td>' + esc(r.n) + '</td><td class="small">' + esc(r.fix) + '</td></tr>'; }).join('') + '</tbody></table>'
      + (v.scope_proposal.length ? '<p class="small">Subnets to add to the scan scope: <b>' + esc(v.scope_proposal.join(', ')) + '</b> - <a href="vuln-scans.html">Vulnerability Scans &rarr; Scope</a> (the Network Assistant fills it).</p>' : '') : '<div class="empty">Every assessable connected asset is scanned or in a scan now.</div>';
    var can = RANK[ROLE] >= RANK.operator, R = v.rescan;
    $('rescan').innerHTML = R.batches.length ? '<p class="small">' + esc(R.hosts) + ' address(es) whose fix is a rescan, in ' + esc(R.batches.length) + ' batch(es):</p>' + R.batches.map(function (b) { return '<div class="nx"><span class="pill info">' + b.n + '</span><div style="flex:1">' + esc(b.hosts) + ' address(es)<div class="hint">' + esc(b.targets.slice(0, 8).join(', ') + (b.targets.length > 8 ? ' …' : '')) + '</div></div></div>'; }).join('')
      + (can ? '<button type="button" id="filebtn" style="margin-top:8px">File the rescan</button>' : '') + '<p class="hint">' + esc(R.note) + '</p>' : '<div class="empty">' + esc(R.note) + '</div>';
    var L = v.assets.filter(function (r) { return (!FLT || (FLT === 'persistent' ? r.persistent : r.status === FLT)) && (!REASON || r.reason === REASON); });
    $('ac').textContent = L.length + ' of ' + v.assets.length + (REASON ? ' · ' + REASON.replace('_', ' ') : '');
    $('assets').innerHTML = L.length ? '<table><thead><tr><th>Asset</th><th>Addresses</th><th>Status</th><th>Why / fix</th><th>Last scan</th></tr></thead><tbody>' + L.slice(0, 1000).map(function (r) {
      return '<tr><td><b>' + esc(r.name) + '</b><div class="hint">' + esc([r.type, r.site, r.owner].filter(Boolean).join(' · ')) + '</div></td><td class="small">' + esc(r.ips.join(', ') || '—') + '</td><td><span class="pill ' + STC[r.status] + '">' + esc(r.status === 'failed' ? 'not scanned' : r.status === 'excluded' ? 'left out' : r.status) + '</span>' + (r.persistent ? '<span class="pill bad">2+ days</span>' : '') + '</td>'
        + '<td class="small">' + (r.why ? '<b>' + esc(r.why) + '</b>' + (r.detail ? ' - ' + esc(r.detail) : '') + '<div>' + esc(r.fix || '') + '</div>' : '—') + '</td><td class="small">' + esc(r.last_scan ? r.last_scan.slice(0, 10) + (r.tool ? ' · ' + r.tool : '') : 'never') + '</td></tr>'; }).join('') + '</tbody></table>' : '<div class="empty">No asset matches.</div>';
    $('note').textContent = v.note; $('up').textContent = 'Updated ' + String(v.generated_at).slice(11, 16) + ' UTC'; }
  function fileDlg() { $('dlgt').textContent = 'File the rescan'; $('dlgb').innerHTML = '<p>' + esc(V.rescan.batches.length) + ' scan request(s) for ' + esc(V.rescan.hosts) + ' address(es) will be filed in Vulnerability Scans, with staggered windows. A different person approves each before anything is sent.</p><div class="form"><label for="f-hours">Hours per batch</label><input id="f-hours" type="number" min="1" max="12" value="6"></div>'; $('dlg').showModal(); }
  function fileIt() { $('dlgok').disabled = true; req('POST', '/scan-assurance/rescan', { hours: Number($('f-hours').value) || 6 }).then(function (r) { $('dlg').close(); toast(r.filed.length + ' scan request(s) filed: ' + r.filed.map(function (f) { return f.scan; }).join(', ') + ' - a different person approves them'); load(); }, function (e) { toast(e.message); }).then(function () { $('dlgok').disabled = false; }); }
  function rep(fmt) { req('GET', '/scan-assurance/report?format=' + fmt).then(function (r) { var u = URL.createObjectURL(new Blob([fmt === 'csv' ? '﻿' + r.csv : r.html], { type: fmt === 'csv' ? 'text/csv' : 'text/html' }));
    if (fmt === 'html') { if (!window.open(u, '_blank', 'noopener')) toast('Allow pop-ups to open the statement'); } else { var a = document.createElement('a'); a.href = u; a.download = r.filename; document.body.appendChild(a); a.click(); a.remove(); } setTimeout(function () { URL.revokeObjectURL(u); }, 60000); toast('Recorded in the audit trail'); }, function (e) { toast(e.message); }); }
  document.addEventListener('click', function (ev) { var t = ev.target, x;
    if ((x = t.closest('[data-reason]'))) { var r = x.getAttribute('data-reason'); REASON = REASON === r ? '' : r; if (REASON) { FLT = ''; $('flt').value = ''; } draw(); return; }
    if (t.id === 'filebtn') return fileDlg(); if (t.id === 'dlgok') return fileIt(); if (t.id === 'dlgx') return $('dlg').close();
    if (t.id === 'refresh') return load(); if (t.id === 'rhtml') return rep('html'); if (t.id === 'rcsv') return rep('csv'); });
  $('flt').addEventListener('change', function () { FLT = $('flt').value; draw(); });
  (function () { var w = new XMLHttpRequest(); w.open('GET', '/dashboards/whoami.json'); w.zybQuiet = true; w.onload = function () { try { var j = JSON.parse(w.responseText), r = String(j.role || '').toLowerCase(); if (RANK[r] != null) ROLE = r; } catch (e) { /* not signed in: viewer */ } load(); }; w.onerror = load; w.send(); })();
})();
